#include <stdio.h>
#include <string.h>

/* split a comma separated line */

static char *fields[8];

int split_line(char *line) {
  int n = 0;
  char *tok = strtok(line, ",");
  while (tok != NULL) {
    fields[n] = tok;
    n = n + 1;
    tok = strtok(NULL, ",");
  }
  return n;
}

