#define DELIM ","

int split_line(char *line, char **fields, int max) {
  char *save = NULL;
  int n = 0;
  for (char *tok = strtok_r(line, DELIM, &save); tok != NULL; tok = strtok_r(NULL, DELIM, &save)) {
    if (n >= max) return -1;
    fields[n] = tok;
    n = n + 1;
  }
  return n;
}

int split_line(const char *line, char *work, size_t work_size, char **fields, int max) {
  size_t len = strlen(line);
  if (len >= work_size) return -1;
  memcpy(work, line, len + 1);
  char *save = NULL;
  int n = 0;
  for (char *tok = strtok_r(work, DELIM, &save); tok != NULL; tok = strtok_r(NULL, DELIM, &save)) {
    if (n >= max) return -1;
    fields[n] = tok;
    n = n + 1;
  }
  return n;
}
